<template>
<div class="container">
    <div class="card mt-3 mb-4 border-2">
        <div class="card-header bg-success">
            <h4 class="text-warning">USER PROFILE</h4>
        </div>

        <div class="card-body bg-warning">
        
            <form enctype="multipart/form-data">
            <div class="row">
                <div class="col">
                       <div class="mb-3">
                            <input type="text" v-model="userData.firstname" required class="form-control" placeholder="enter First Name">
                       </div>
                       <div class="mb-3">
                            <input type="text" v-model="userData.lastname" required class="form-control" placeholder="enter Last Name">
                       </div>
                       <div class="mb-3">
                            <input type="email" v-model="userData.email" class="form-control" :disabled="true">
                       </div>
                       <div class="mb-3">
                            <input type="text" v-model="userData.mobile" required class="form-control" placeholder="enter Mobile No.">
                       </div>                    
                </div>
                <div class="col">

                    <div class="mb-3 text-left">
                        <img id="pix" class="userpic" :src="previewUrl" />
                    </div>
                    <div class="mb-3 text-left">
                        <input @change="changeProfilepic" class="form-control form-control-sm" id="userpic" type="file" accept=".png, .jpg, .jpeg, .gif">
                    </div>

                </div>
            </div>

            <div class="row">

                <div class="col">
                    <!-- CHANGE PASSWORD CHECK BOX -->
                    <div v-if="chkchangepassword">
                        <div class="form-check">
                            <input @change="changePassword" class="form-check-input check-box" type="checkbox" value="" v-model="changepwd2">
                            <label class="form-check-label" for="changepwd">
                            Change Password
                            </label>
                        </div>
                    </div>

                    <div v-if="changepwd2">
                          <div class="mb-3">
                            <input type="password" required class="form-control" v-model="userData.password" placeholder="enter new Password" autocomplete="off">
                          </div>
                          <div class="mb-3">
                            <input type="password" required class="form-control" v-model="userData.confpassword" placeholder="confirm new Password" autocomplete="off">
                          </div>
                          <button @click="changePwd" type="button" class="btn btn-primary">change password</button>
                    </div>
                    <div v-if="twofactor">
                            <img class="qrcode1" :src="userData.qrcodeurl" alt="qrcodeurl"/>
                    </div>
                    
                </div>

                <div class="col">
                    <!-- 2-FACTORR AUTHENTICATOR -->
                   <div v-if="twofactorauthenticator">
                     <div class="form-check">
                        <input @change="onetimePassword" class="form-check-input check-box" type="checkbox" value="" v-model="twofactor">
                        <label class="form-check-label" for="twofactor">
                            2-Factor Authenticator
                        </label>
                     </div>
                    </div>

                    <div v-if="twofactor">
                        <p class='text-danger'><strong>Requirements</strong></p>
                        <p>You need to install <strong>Google or Microsoft Authenticator</strong> in your Mobile Phone, once installed, click Enable Button below, and <strong>SCAN QR CODE</strong>, next time you login, another dialog window will appear, then enter the <strong>OTP CODE</strong> from your Mobile Phone in order for you to login.</p>
                        <button @click="enableMFA" type="button" class="btn btn-primary mx-1 mb-1">Enable</button>
                        <button @click="disableMFA" type="button" class="btn btn-secondary">Disable</button>
                   </div>



                </div>

            </div>
                <div v-if="!userData.showSave">
                    <button @click="submitProfileForm" id="save" type="submit" class="btn btn-success text-warning">save</button>
                </div>            
            </form>
        </div>
        <div class="card-footer text-danger fsize-12">
            {{userData.profileMsg}}
        </div>
    </div>

</div>
</template>

<script setup lang="ts">
    import {reactive, ref, onMounted} from 'vue'
    import axios from 'axios';

    const api = axios.create({
    baseURL: "http://127.0.0.1:8000",
    headers: {'Accept': 'application/json',
                'Content-Type': 'application/json'}
    })

    const mapi = axios.create({
        baseURL: "http://127.0.0.1:8000"
    })

    const previewUrl = ref<string | null>(null);
    const chkchangepassword = ref(true);
    const twofactorauthenticator = ref(true);
    const changepwd2 = ref(false)
    const twofactor = ref(false)
        
    const userData = reactive({
        firstname: '',
        lastname: '',
        email: '',
        mobile: '',
        password: '',
        confpassword: '',
        profileMsg: '',
        qrcodeurl: '',
        profilepic: '',
        userId: '',
        token: '',
        showSave: false
    });

    function fetchData(idno: any) {
        api.get(`/api/getuserid/${idno}`, { headers: {
            Authorization: `Bearer ${userData.token}`
        }} )
            .then((res) => {
                userData.firstname = res.data.user.firstname;
                userData.lastname = res.data.user.lastname;
                userData.email = res.data.user.email;
                userData.mobile = res.data.user.mobile;
                let userpic: string = `http://127.0.0.1:8000/users/${res.data.user.profilepic}`;
                previewUrl.value = userpic;
                if (res.data.user.qrcodeurl !== null) {
                    userData.qrcodeurl = res.data.user.qrcodeurl;
                } else {
                    userData.qrcodeurl = "http://127.0.0.1:8000/images/qrcode.png";
                }
                userData.profileMsg = res.data.user.message;
              }, (error: any) => {
                    userData.profileMsg = error.response.data.message;
                    window.setTimeout(() => {
                        userData.profileMsg = "";
                    },3000);
            });                
    }

    onMounted(() => {
        const usrid = sessionStorage.getItem('USERID');
        if (usrid !== null) {
            userData.userId = usrid
        } else {
            userData.userId = '';
        }
        const tokenid = sessionStorage.getItem("TOKEN");
        if (tokenid !== null) {
            userData.token = tokenid;
        } else {
            userData.token = '';
        }
        fetchData(userData.userId);
    });

    async function submitProfileForm(e: any) {
        e.preventDefault();
        userData.profileMsg = 'please wait...';
        const data =JSON.stringify({ lastname: userData.lastname, 
                firstname: userData.firstname, mobile: userData.mobile });

            await api.patch(`/api/updateprofile/${userData.userId}`, data, { headers: {
            Authorization: `Bearer ${userData.token}`
            }} )
            .then((res: any) => {
                    userData.profileMsg = res.data.message;
                    window.setTimeout(() => {
                        userData.profileMsg = '';
                    }, 3000);
              }, (error: any) => {
                    userData.profileMsg = error.response.data.message;
                    window.setTimeout(() => {
                        userData.profileMsg = '';
                    }, 3000);
            }); 
    }

    function changePassword(event: any) {
        const isCheckedPwd = event.target.checked;
        if (isCheckedPwd) {
            changepwd2.value = true;
            userData.showSave = true;
        } else {
            changepwd2.value = false;
            userData.showSave = false;
        }
    }

    function onetimePassword(event: any) {
        const isCheckedMfa = event.target.checked;
        if (isCheckedMfa) {
            twofactor.value = true;
            userData.showSave = true;
        } else {
            twofactor.value;
            userData.showSave = false;
        }    
    }

    async function enableMFA(e: any) {
        e.preventDefault();
        const data =JSON.stringify({ Twofactorenabled: true });
            await api.patch(`/api/activatemfa/${userData.userId}`, data, { headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${userData.token}`
            }} )
            .then((res: any) => {
                userData.profileMsg = res.data.message;
                    window.setTimeout(() => {
                        userData.qrcodeurl = res.data.qrcodeurl;
                        userData.profileMsg = '';
                    }, 3000);
              }, (error: any) => {
                userData.profileMsg = error.response.data.message;
                    window.setTimeout(() => {
                        userData.profileMsg = '';
                    }, 3000);
            });        
    }

    async function disableMFA(e: any) {
        e.preventDefault();
        const data =JSON.stringify({ Twofactorenabled: false });
            await api.patch(`/api/activatemfa/${userData.userId}`, data, { headers: {
                Authorization: `Bearer ${userData.token}`
            }} )
            .then((res: any) => {
                userData.qrcodeurl = '';
                userData.profileMsg = res.data.message;
                userData.qrcodeurl = "http://127.0.0.1:8000/images/qrcode.png";
                    window.setTimeout(() => {
                        userData.profileMsg = '';
                    }, 1000);
              }, (error: any) => {
                userData.profileMsg = error.response.data.message;
                    window.setTimeout(() => {
                        userData.profileMsg = '';
                    }, 3000);
            });              
    }


    async function changePwd(e: any) {
        e.preventDefault();
        if (userData.password === '') {
            userData.profileMsg = "Please enter new password.";
            window.setTimeout(() => {
                    userData.profileMsg = "";
                    userData.qrcodeurl = "/images/qrcode.png";
                },3000);
            return;
        }
        if (userData.confpassword === '') {
            userData.profileMsg = "Please confirm new password.";
            window.setTimeout(() => {
                    userData.profileMsg = "";
                },3000);
            return;
        }

        if (userData.password !== '' && userData.confpassword) {
            if (userData.password !== userData.confpassword) {
                userData.profileMsg = "New Password does not matched.";
                window.setTimeout(() => {
                    userData.profileMsg = "";
                },3000);
            }
        }
        else
        {
            userData.profileMsg = 'please enter password';
            window.setTimeout(() => {
                userData.profileMsg = "";
            },3000);
        }

        const data =JSON.stringify({ password: userData.password });
            await api.patch(`/api/changepassword/${userData.userId}`, data, { headers: {
            Authorization: `Bearer ${userData.token}`
            }} )
            .then((res) => {
                if (res.data.statuscode == 200) {
                    userData.profileMsg = res.data.message;
                    window.setTimeout(() => {
                        userData.profileMsg = '';
                    }, 3000);
                    return;
                } else {
                    userData.profileMsg = res.data.message;
                  window.setTimeout(() => {
                    userData.profileMsg = '';
                    }, 3000);
                    return;
                }
              }, (error: any) => {
                userData.profileMsg = error.response.data.message;
                    window.setTimeout(() => {
                        userData.profileMsg = '';
                    }, 3000);
            });
    }

    async function changeProfilepic(event: Event) {
        const target = event.target as HTMLInputElement;
        if (target.files && target.files.length > 0) {
            const file = target.files[0];
            if (file) {
                previewUrl.value = URL.createObjectURL(file);
                const formdata = new FormData();
                formdata.append('id', userData.userId);
                formdata.append('profilepic', file);

                await mapi.post("/api/uploadpicture", formdata, { 
                    headers: {                    
                        Authorization: `Bearer ${userData.token}`,
                        'Accept': 'application/json',
                        'Content-Type': 'multipart/form-data'
                    }
                })
                .then((res: any) => {
                        userData.profileMsg = res.data.message;
                        window.setTimeout(() => {
                            sessionStorage.removeItem('USERPIC');
                            let userpic: string = `http://127.0.0.1:8000/users/${res.data.profilepic}`;
                            sessionStorage.setItem('USERPIC',userpic);
                            userData.profileMsg = '';
                            reloadNuxtApp({path: '/'})
                        }, 3000);
                }, (error: any) => {
                        if (error.response) {
                            console.log(error.response.data.message);
                            userData.profileMsg = error.response.data.message;
                        } else {
                            console.log(error.message);
                            userData.profileMsg = error.message;
                        }
                        window.setTimeout(() => {
                            userData.profileMsg = '';
                        }, 3000);
                });

            }                        
        }
    }
</script>

<style scoped>

.userpic {
    width: 150px;
    height: 150px;
}
.fsize-12 {
    font-size: 12px;
}
.qrcode1 {
  float: right;
  width: 200px;
  height: 200px;
}
.qrcode2 {
  float: right;
  width: 200px;
  height: 200px;
  opacity: 0.5;
}
.btn-1 {
  max-width: 100px!important;
}
.btn-2 {
  float: left!important;
}
#save {
  margin-top: 30px!important;
}
@media (max-width: 575.98px) {
  .btn-2 {
    float: right!important;
  }
  #save {
    margin-top: 30px!important;
  }

 }
</style>
